using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using PeerChatDesktop;
class LocalDeletionUiTest {
    static void Check(bool value,string why){if(!value)throw new Exception(why);}
    static string Id(char ch,int length=32){return new string(ch,length);}
    static MessageModel Text(string id,string text="hello"){return new MessageModel{Data=new MessageData{id=id,text=text,sender=Id('a',64),time=1},Outgoing=false};}
    static void Projection(){
        var model=new ChatViewModel();var peer=Id('a',64);var otherPeer=Id('b',64);var conversation=model.Get(peer);var keep=Text(Id('1'));var remove=Text(Id('2'));conversation.Messages.Add(keep);conversation.Messages.Add(remove);
        conversation.LocalDeletions.Hide(LocalDeletionState.MessageIds(remove));conversation.Messages.Remove(remove);model.Apply(new CoreEvent{kind=6,peer=peer,messages=new[]{remove.Data,keep.Data}});Check(conversation.Messages.Count==1&&conversation.Messages[0]==keep,"deleted text returned from an already queued history page");
        conversation.LocalDeletions.ExpectRefresh(false);var pending=Text("local-attachment:uncommitted");conversation.Messages.Add(pending);model.Apply(new CoreEvent{kind=6,peer=peer,text="history_cleared",messages=new[]{keep.Data}});Check(conversation.Messages.Count==2&&conversation.Messages.Contains(pending)&&conversation.LocalDeletions.ExpectedRefreshes==0,"single-message native refresh wiped another visible or pending bubble");
        var transfer=Id('3');var logical=Id('4');conversation.LocalDeletions.Hide(new[]{transfer});Check(!ChatAttachmentProjection.Apply(conversation,new CoreAdapter.FileTransferData{id=transfer,logicalId=logical,peer=peer,name="photo.png",size=10,state=3,sending=true}),"hidden transfer returned through a cached snapshot");model.Apply(new CoreEvent{kind=5,peer=peer,messages=new[]{Text(logical).Data}});Check(!conversation.Messages.Any(message=>message.Data.id==logical),"cached transfer alias resurrected as a logical message");
        var separate=model.Get(otherPeer);model.Apply(new CoreEvent{kind=5,peer=otherPeer,messages=new[]{remove.Data}});Check(separate.Messages.Count==1,"deletion affected another conversation");
        bool reused;var bound=model.BindFriend(7,"friend",peer,new[]{peer,Id('c',64)},out reused);Check(LocalDeletionState.Peers(bound).Length==2&&bound.LocalDeletions.Hidden(remove.Data.id),"account friend binding lost deleted IDs or peer aliases");var older=model.Get(Id('d',64));older.LocalDeletions.Hide(new[]{Id('5')});model.BindFriend(7,"friend",older.Contact.peer,new[]{older.Contact.peer},out reused);Check(bound.LocalDeletions.Hidden(Id('5')),"merged device conversation restored a deleted message");
        conversation=bound;conversation.LocalDeletions.Hide(conversation.Messages.SelectMany(message=>LocalDeletionState.MessageIds(message)));conversation.Messages.Clear();conversation.LocalDeletions.ExpectRefresh(true);conversation.LocalDeletions.ExpectRefresh(true);model.Apply(new CoreEvent{kind=6,peer=peer,messages=new[]{Text(Id('6')).Data}});Check(conversation.Messages.Count==0,"unknown stale page repopulated a cleared history");model.Apply(new CoreEvent{kind=6,peer=peer,text="history_cleared",messages=new MessageData[0]});Check(conversation.LocalDeletions.ClearingHistory,"first alias barrier prematurely exposed remaining old histories");model.Apply(new CoreEvent{kind=6,peer=peer,text="history_cleared",messages=new MessageData[0]});Check(!conversation.LocalDeletions.ClearingHistory,"last native ordering barrier did not reopen new messages");model.Apply(new CoreEvent{kind=5,peer=peer,messages=new[]{Text(Id('7')).Data}});Check(conversation.Messages.Count==1&&model.Conversations.Values.Contains(conversation)&&conversation.IsFriend,"clearing conversation removed friendship or blocked future messages");
        var group=new GroupModel{Data=new GroupData{id=Id('e'),name="group"}};model.GroupChats.Add(group.Id,group);group.LocalDeletions.Hide(new[]{transfer});Check(!GroupAttachmentProjection.Apply(group,new CoreAdapter.GroupAttachmentData{id=transfer,logicalId=logical,group=group.Id,name="photo.png",size=10,state="uploading"}),"group attachment snapshot resurrected a deleted bubble");model.Apply(new CoreEvent{kind=10,peer=group.Id,groupEvents=new[]{new GroupEventData{id=logical,text="reference"}}});Check(group.Messages.Count==0,"deleted group attachment reference returned");group.LocalDeletions.ExpectRefresh(true);model.Apply(new CoreEvent{kind=11,peer=group.Id,groupEvents=new[]{new GroupEventData{id=Id('8'),text="old"}}});Check(group.Messages.Count==0,"cleared group accepted an in-flight old page");model.Apply(new CoreEvent{kind=11,peer=group.Id,text="history_cleared",groupEvents=new GroupEventData[0]});model.Apply(new CoreEvent{kind=10,peer=group.Id,groupEvents=new[]{new GroupEventData{id=Id('9'),sender=peer,text="new"}}});Check(group.Messages.Count==1&&model.GroupChats.ContainsKey(group.Id),"clearing group history removed group membership or blocked new messages");
    }
    static void Pending(){
        var source=new LocalAttachmentSource("photo.png",new byte[]{1},null);var gate=new TaskCompletionSource<string>();int sends=0,cancels=0;string deleted=null;var pending=new PendingOutgoingAttachment(source,()=>true,()=>{sends++;return gate.Task;},id=>{cancels++;return Task.CompletedTask;},id=>deleted=id);
        // Delete can precede the deferred send continuation. It hides presentation,
        // while the already requested send and its eventual exact-ID tombstone continue.
        pending.DeletePresentation();Check(!pending.CanRetry&&!pending.CancelRequested,"local deletion changed delivery intent");var running=pending.RunAsync();pending.BeginNativeAdmission();Check(pending.NativeAdmissionInFlight&&sends==1,"deleted pending row lost the native-admission projection fence");gate.SetResult(Id('a'));running.GetAwaiter().GetResult();Check(deleted==Id('a')&&cancels==0&&pending.RunCompleted&&!pending.NativeAdmissionInFlight,"pending deletion canceled/unsent delivery or lost exact eventual native ID");pending.RestorePresentation();Check(!pending.LocalDeleted&&!pending.CancelRequested&&!pending.CanRetry,"failed pending deletion did not restore the accepted send");pending.RunAsync().GetAwaiter().GetResult();Check(sends==1,"deleted pending attachment was sent twice");
        var ids=LocalDeletionState.MessageIds(new MessageModel{Data=new MessageData{id="local-attachment:temporary"},PendingAttachment=pending});Check(ids.SequenceEqual(new[]{Id('a')}),"presentation IDs reached native deletion");
    }
    static void Completion(){
        string peer=Id('a',64),id=Id('b');var state=new LocalDeletionState();var completions=new LocalDeletionCompletion();bool visible=true,failed=false;
        Action<bool> result=success=>{state.AcceptRefresh();state.EndPending(new[]{id});if(success){state.Hide(new[]{id});visible=false;}else failed=true;};
        state.BeginPending(new[]{id});state.ExpectRefresh(false);completions.Register(peer,id,false,result);Check(state.Hidden(id)&&visible,"queue acceptance was claimed as durable deletion");Check(!completions.Complete(peer,Id('c'),false,true)&&!completions.Complete(peer,id,true,true)&&visible,"unrelated native result completed local deletion");Check(completions.Complete(peer,id,false,false)&&visible&&failed&&!state.Hidden(id)&&state.ExpectedRefreshes==0,"native storage failure permanently hid the UI message");
        state.BeginPending(new[]{id});state.ExpectRefresh(false);completions.Register(peer,id,false,result);Check(completions.Complete(peer,id,false,true)&&!visible&&state.Hidden(id),"matching durable native success did not commit the tombstone");Check(!completions.Complete(peer,id,false,true),"duplicate success consumed another deletion");
        int order=0;completions.Register(peer,id,false,success=>{Check(order==0&&!success,"same-target completion did not preserve native queue order");order++;});completions.Register(peer,id,false,success=>{Check(order==1&&success,"second target completion mismatched");order++;});completions.Complete(peer,id,false,false);completions.Complete(peer,id,false,true);Check(order==2,"correlated completion queue lost a request");
        var transient=new LocalDeletionState();transient.ExpectRefresh(true);transient.ExpectRefresh(true);transient.AcceptRefresh();Check(transient.ClearingHistory,"partial aliased failure released history barrier early");transient.AcceptRefresh();Check(!transient.ClearingHistory,"failed history batch kept a permanent visibility barrier");
        Check(LocalDeletionState.MessageId(Id('e',64),true)&&!LocalDeletionState.MessageId(Id('e',64),false),"legacy group event ID was rejected or accepted for DM");
    }
    static void Menu(){
        var first=Text(Id('1'));var second=Text(Id('2'));var bubble=new MessageBubble{DataContext=first};Check(bubble.ContextMenu.Items.Count==1&&((MenuItem)bubble.ContextMenu.Items[0]).Header.ToString()=="Delete message from this device’s history"&&Stylus.GetIsPressAndHoldEnabled(bubble),"message right-click/press-and-hold menu missing");MessageModel deleted=null;bool scope=true;bubble.AddHandler(MessageBubble.LocalDeleteEvent,new RoutedEventHandler((s,e)=>{var request=(LocalDeleteMessageEventArgs)e;var captured=request.Message;request.Commit=()=>{if(scope)deleted=captured;};}));
        var constructor=typeof(ContextMenuEventArgs).GetConstructors(BindingFlags.Instance|BindingFlags.NonPublic).First(value=>value.GetParameters().Length==2);var opening=(ContextMenuEventArgs)constructor.Invoke(new object[]{bubble,true});opening.RoutedEvent=ContextMenuService.ContextMenuOpeningEvent;bubble.RaiseEvent(opening);bubble.DataContext=second;((MenuItem)bubble.ContextMenu.Items[0]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(deleted==first,"context menu action followed a changed selection instead of the captured message");deleted=null;scope=false;((MenuItem)bubble.ContextMenu.Items[0]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(deleted==null,"stale profile menu committed a deletion");
        var method=typeof(CoreAdapter).GetMethod("ui_delete_local",BindingFlags.Static|BindingFlags.NonPublic);var import=(DllImportAttribute)Attribute.GetCustomAttribute(method,typeof(DllImportAttribute));Check(import.CharSet==CharSet.Unicode&&import.CallingConvention==CallingConvention.Cdecl,"deletion ABI changed");Check(LocalDeletionState.Canonical(Id('a',64),64)&&LocalDeletionState.Canonical(Id('a'),32)&&!LocalDeletionState.Canonical("local-attachment:temporary",32)&&!LocalDeletionState.Canonical(Id('A'),32),"native deletion identifier validation changed");
    }
    [STAThread]static int Main(){try{new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Projection();Pending();Completion();Menu();Console.WriteLine("PASS local deletion UI: scoped text/photo/group filtering, cached logical/transfer aliases, old-page barriers, friend/group retention, future messages, pending exact-ID deletion without unsend, captured right-click/hold menu, native ABI.");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
